import{_ as r,a as l,e as i,l as a,at as d,Q as o,t as n}from"./chunks/framework.D7hrsxJP.js";const k=JSON.parse('{"title":"计算机网络","description":"","frontmatter":{"title":"计算机网络","tags":["interview","network"]},"headers":[],"relativePath":"interview/01-Network.md","filePath":"interview/01-Network.md","lastUpdated":1761045430000}'),h={name:"interview/01-Network.md"},s={id:"frontmatter-title",tabindex:"-1"};function c(e,t,T,g,P,b){return i(),l("div",null,[t[1]||(t[1]=a("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /vite-press/interview/01-Network.md for this page in Markdown format",-1)),a("h1",s,[o(n(e.$frontmatter.title)+" ",1),t[0]||(t[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),t[2]||(t[2]=d('<h2 id="🧠-一、基础概念类" tabindex="-1">🧠 一、基础概念类 <a class="header-anchor" href="#🧠-一、基础概念类" aria-label="Permalink to “🧠 一、基础概念类”">​</a></h2><h3 id="_1-什么是-tcp-和-udp-它们有什么区别" tabindex="-1">1. 什么是 TCP 和 UDP？它们有什么区别？ <a class="header-anchor" href="#_1-什么是-tcp-和-udp-它们有什么区别" aria-label="Permalink to “1. 什么是 TCP 和 UDP？它们有什么区别？”">​</a></h3><ul><li><strong>TCP（传输控制协议）</strong>：面向连接、可靠传输、顺序保证（如 HTTP）。</li><li><strong>UDP（用户数据报协议）</strong>：无连接、不保证顺序、无重传机制（如 DNS、视频流）。</li></ul><p><strong>区别总结：</strong></p><table tabindex="0"><thead><tr><th>特性</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接性</td><td>面向连接</td><td>无连接</td></tr><tr><td>可靠性</td><td>可靠（有确认、重传）</td><td>不可靠</td></tr><tr><td>顺序保证</td><td>有</td><td>无</td></tr><tr><td>速度</td><td>慢</td><td>快</td></tr><tr><td>应用场景</td><td>HTTP、FTP</td><td>DNS、视频直播等</td></tr></tbody></table><h3 id="_2-http-和-https-的区别是什么" tabindex="-1">2. HTTP 和 HTTPS 的区别是什么？ <a class="header-anchor" href="#_2-http-和-https-的区别是什么" aria-label="Permalink to “2. HTTP 和 HTTPS 的区别是什么？”">​</a></h3><ul><li><strong>HTTPS = HTTP + TLS/SSL 加密层</strong>。</li><li>区别： <ul><li><strong>加密通信</strong>：HTTPS 使用非对称+对称加密，保障数据安全。</li><li><strong>身份验证</strong>：HTTPS 需证书认证，避免中间人攻击。</li><li><strong>端口不同</strong>：HTTP 使用 80，HTTPS 使用 443。</li><li><strong>性能开销</strong>：HTTPS 加解密带来略微性能损耗。</li></ul></li></ul><h3 id="_3-什么是三次握手和四次挥手" tabindex="-1">3. 什么是三次握手和四次挥手？ <a class="header-anchor" href="#_3-什么是三次握手和四次挥手" aria-label="Permalink to “3. 什么是三次握手和四次挥手？”">​</a></h3><h4 id="tcp-三次握手-建立连接" tabindex="-1">TCP 三次握手（建立连接）： <a class="header-anchor" href="#tcp-三次握手-建立连接" aria-label="Permalink to “TCP 三次握手（建立连接）：”">​</a></h4><ol><li>客户端发送 SYN（同步序列号）；</li><li>服务端返回 SYN + ACK；</li><li>客户端再发 ACK，连接建立。</li></ol><h4 id="tcp-四次挥手-断开连接" tabindex="-1">TCP 四次挥手（断开连接）： <a class="header-anchor" href="#tcp-四次挥手-断开连接" aria-label="Permalink to “TCP 四次挥手（断开连接）：”">​</a></h4><ol><li>客户端发 FIN；</li><li>服务端返回 ACK；</li><li>服务端再发 FIN；</li><li>客户端返回 ACK，连接断开。</li></ol><h2 id="🌐-二、http-协议相关" tabindex="-1">🌐 二、HTTP 协议相关 <a class="header-anchor" href="#🌐-二、http-协议相关" aria-label="Permalink to “🌐 二、HTTP 协议相关”">​</a></h2><h3 id="_4-常见-http-状态码有哪些" tabindex="-1">4. 常见 HTTP 状态码有哪些？ <a class="header-anchor" href="#_4-常见-http-状态码有哪些" aria-label="Permalink to “4. 常见 HTTP 状态码有哪些？”">​</a></h3><ul><li><strong>200</strong>：成功</li><li><strong>301/302</strong>：重定向</li><li><strong>304</strong>：缓存命中，未修改</li><li><strong>400</strong>：请求错误</li><li><strong>401</strong>：未认证</li><li><strong>403</strong>：禁止访问</li><li><strong>404</strong>：未找到</li><li><strong>500</strong>：服务器内部错误</li></ul><h3 id="_5-http-请求有哪些方法-各自作用" tabindex="-1">5. HTTP 请求有哪些方法？各自作用？ <a class="header-anchor" href="#_5-http-请求有哪些方法-各自作用" aria-label="Permalink to “5. HTTP 请求有哪些方法？各自作用？”">​</a></h3><ul><li><strong>GET</strong>：获取资源，幂等</li><li><strong>POST</strong>：创建资源，非幂等</li><li><strong>PUT</strong>：更新资源（整体）</li><li><strong>PATCH</strong>：部分更新</li><li><strong>DELETE</strong>：删除资源</li></ul><h3 id="_6-cookie、session、localstorage、token-的区别" tabindex="-1">6. Cookie、Session、LocalStorage、Token 的区别？ <a class="header-anchor" href="#_6-cookie、session、localstorage、token-的区别" aria-label="Permalink to “6. Cookie、Session、LocalStorage、Token 的区别？”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>Cookie</th><th>Session</th><th>LocalStorage</th><th>Token</th></tr></thead><tbody><tr><td>存储位置</td><td>浏览器</td><td>服务端</td><td>浏览器</td><td>浏览器</td></tr><tr><td>有效范围</td><td>同源 + 路径</td><td>服务端</td><td>同源</td><td>同源</td></tr><tr><td>生命周期</td><td>设定过期时间</td><td>会话关闭失效</td><td>永久除非手动清除</td><td>通常含过期时间</td></tr><tr><td>安全性</td><td>低</td><td>中等</td><td>低</td><td>高（若配合 HTTPS）</td></tr><tr><td>前后端分离推荐</td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr></tbody></table><h3 id="_7-什么是跨域-如何解决跨域问题" tabindex="-1">7. 什么是跨域？如何解决跨域问题？ <a class="header-anchor" href="#_7-什么是跨域-如何解决跨域问题" aria-label="Permalink to “7. 什么是跨域？如何解决跨域问题？”">​</a></h3><p><strong>跨域</strong>：浏览器的同源策略阻止不同源的请求（域名、协议、端口不同）。</p><p><strong>解决方案</strong>：</p><ul><li>CORS（服务器设置 <code>Access-Control-Allow-Origin</code>）</li><li>JSONP（仅支持 GET）</li><li>代理转发（如 <code>devServer.proxy</code>）</li><li>WebSocket（不受同源策略限制）</li><li>postMessage（跨 iframe 通信）</li></ul><h2 id="🚀-三、性能优化类" tabindex="-1">🚀 三、性能优化类 <a class="header-anchor" href="#🚀-三、性能优化类" aria-label="Permalink to “🚀 三、性能优化类”">​</a></h2><h3 id="_8-什么是浏览器缓存-有哪些类型" tabindex="-1">8. 什么是浏览器缓存？有哪些类型？ <a class="header-anchor" href="#_8-什么是浏览器缓存-有哪些类型" aria-label="Permalink to “8. 什么是浏览器缓存？有哪些类型？”">​</a></h3><p><strong>缓存类型</strong>：</p><ul><li><strong>强缓存</strong>： <ul><li><code>Expires</code>：HTTP 1.0 的绝对时间</li><li><code>Cache-Control: max-age</code>：相对时间</li></ul></li><li><strong>协商缓存</strong>： <ul><li><code>Last-Modified</code> + <code>If-Modified-Since</code></li><li><code>ETag</code> + <code>If-None-Match</code></li></ul></li></ul><p><strong>流程</strong>：</p><ol><li>先查强缓存（命中直接用）；</li><li>如果失效，则进行协商缓存（向服务器确认资源是否变更）；</li><li>若无变更，返回 304。</li></ol><h3 id="_9-http1-1、http2、http3-有什么区别" tabindex="-1">9. HTTP1.1、HTTP2、HTTP3 有什么区别？ <a class="header-anchor" href="#_9-http1-1、http2、http3-有什么区别" aria-label="Permalink to “9. HTTP1.1、HTTP2、HTTP3 有什么区别？”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>HTTP/1.1</th><th>HTTP/2</th><th>HTTP/3</th></tr></thead><tbody><tr><td>多路复用</td><td>❌ 串行阻塞</td><td>✅ 同一连接复用</td><td>✅ 更高效</td></tr><tr><td>头部压缩</td><td>❌</td><td>✅ HPACK 压缩</td><td>✅ QPACK 压缩</td></tr><tr><td>连接协议</td><td>TCP</td><td>TCP</td><td>QUIC（基于 UDP）</td></tr><tr><td>优势</td><td>普及</td><td>减少阻塞</td><td>快速连接恢复、防丢包</td></tr></tbody></table><h2 id="🔐-四、安全相关" tabindex="-1">🔐 四、安全相关 <a class="header-anchor" href="#🔐-四、安全相关" aria-label="Permalink to “🔐 四、安全相关”">​</a></h2><h3 id="_10-常见的-web-安全问题及防范方法" tabindex="-1">10. 常见的 Web 安全问题及防范方法？ <a class="header-anchor" href="#_10-常见的-web-安全问题及防范方法" aria-label="Permalink to “10. 常见的 Web 安全问题及防范方法？”">​</a></h3><ul><li><strong>XSS（跨站脚本攻击）</strong>：用户输入中注入 JS。 <ul><li>防范：输出内容做 HTML 转义。</li></ul></li><li><strong>CSRF（跨站请求伪造）</strong>：借助用户登录态发起恶意请求。 <ul><li>防范：Token 校验、Referer 检查。</li></ul></li><li><strong>点击劫持</strong>：隐藏 iframe 诱导用户点击。 <ul><li>防范：<code>X-Frame-Options: DENY</code></li></ul></li><li><strong>SQL 注入</strong>：通过拼接 SQL 查询。 <ul><li>防范：使用预编译查询语句（Prepared Statement）。</li></ul></li></ul><h3 id="_11-https-是如何保证安全的" tabindex="-1">11. HTTPS 是如何保证安全的？ <a class="header-anchor" href="#_11-https-是如何保证安全的" aria-label="Permalink to “11. HTTPS 是如何保证安全的？”">​</a></h3><ul><li><strong>混合加密</strong>： <ul><li>非对称加密传输对称密钥；</li><li>对称加密传输数据。</li></ul></li><li><strong>身份认证</strong>：使用数字证书校验服务端身份。</li><li><strong>完整性校验</strong>：防止数据篡改（如 SHA + MAC）。</li></ul><h2 id="📦-五、前端实用网络知识" tabindex="-1">📦 五、前端实用网络知识 <a class="header-anchor" href="#📦-五、前端实用网络知识" aria-label="Permalink to “📦 五、前端实用网络知识”">​</a></h2><h3 id="_12-浏览器输入-url-到页面展示经历了什么" tabindex="-1">12. 浏览器输入 URL 到页面展示经历了什么？ <a class="header-anchor" href="#_12-浏览器输入-url-到页面展示经历了什么" aria-label="Permalink to “12. 浏览器输入 URL 到页面展示经历了什么？”">​</a></h3><ol><li><strong>DNS 解析</strong>（域名转 IP）</li><li><strong>建立 TCP 连接</strong>（三次握手）</li><li><strong>发送 HTTP 请求</strong></li><li><strong>服务器响应 HTML</strong></li><li><strong>浏览器解析 HTML</strong></li><li><strong>加载资源</strong>（CSS、JS、图片）</li><li><strong>渲染页面</strong>（构建 DOM、CSSOM → 渲染树）</li></ol><h3 id="_13-什么是-cdn-它是如何加速的" tabindex="-1">13. 什么是 CDN？它是如何加速的？ <a class="header-anchor" href="#_13-什么是-cdn-它是如何加速的" aria-label="Permalink to “13. 什么是 CDN？它是如何加速的？”">​</a></h3><ul><li>CDN：内容分发网络（Content Delivery Network）。</li><li>加速原理： <ul><li>靠近用户的节点缓存资源；</li><li>减少源站压力和网络延迟；</li><li>DNS 智能调度分配访问节点。</li></ul></li></ul><h3 id="_14-websocket-与-http-的区别" tabindex="-1">14. WebSocket 与 HTTP 的区别？ <a class="header-anchor" href="#_14-websocket-与-http-的区别" aria-label="Permalink to “14. WebSocket 与 HTTP 的区别？”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>HTTP</th><th>WebSocket</th></tr></thead><tbody><tr><td>连接模式</td><td>请求 - 响应</td><td>全双工（长连接）</td></tr><tr><td>保持连接</td><td>否（每次新建）</td><td>是</td></tr><tr><td>数据实时性</td><td>差</td><td>强</td></tr><tr><td>使用场景</td><td>表单、接口请求</td><td>聊天、游戏、推送</td></tr></tbody></table><h2 id="✅-六、补充题-常见延伸问题" tabindex="-1">✅ 六、补充题（常见延伸问题） <a class="header-anchor" href="#✅-六、补充题-常见延伸问题" aria-label="Permalink to “✅ 六、补充题（常见延伸问题）”">​</a></h2><h3 id="_15-浏览器中如何阻止缓存" tabindex="-1">15. 浏览器中如何阻止缓存？ <a class="header-anchor" href="#_15-浏览器中如何阻止缓存" aria-label="Permalink to “15. 浏览器中如何阻止缓存？”">​</a></h3><ul><li>请求头添加： <ul><li><code>Cache-Control: no-cache</code></li><li><code>Pragma: no-cache</code></li><li>在 URL 后添加时间戳：<code>?t=123</code></li></ul></li></ul><h3 id="_16-什么是-cdn-回源-什么是缓存穿透" tabindex="-1">16. 什么是 CDN 回源？什么是缓存穿透？ <a class="header-anchor" href="#_16-什么是-cdn-回源-什么是缓存穿透" aria-label="Permalink to “16. 什么是 CDN 回源？什么是缓存穿透？”">​</a></h3><ul><li><strong>回源</strong>：CDN 缓存未命中时向源站请求。</li><li><strong>缓存穿透</strong>：大量无效请求穿透缓存直接打到数据库或服务端，常用于攻击。</li></ul><h3 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h3><p><a href="./../frontend/network/http">HTTP 和 HTTPS</a></p><p><a href="./../frontend/network/tcp">TCP 与 UDP</a></p><p><a href="./../frontend/network/cors">请求跨域</a></p><p><a href="./../frontend/network/request">资源请求</a></p>',53))])}const u=r(h,[["render",c]]);export{k as __pageData,u as default};
